INSERT INTO scheduled_tasks (id, agent_id, name, description, schedule_type, cron_expression, action, action_params, status, last_run, next_run, run_count, fail_count, created_at, enabled) VALUES
('physician-daily-checkin', 'physician-health', 'Daily Health Check-in', 'Review yesterday''s diet and activity, check health_score trends, flag immediate concerns', 'cron', '30 7 * * *', 'custom_prompt', '{"prompt":"Execute Daily Health Check-in. Step 1: Query diet_log for yesterday''s entries — check meal completeness, macro balance, caloric alignment. Step 2: Query activity_log for yesterday''s physical activity — workout completion, energy expenditure, movement patterns. Step 3: Check days DB health_score trends — is health_score improving, stable, or declining? Step 4: Identify immediate health concerns — missed meals, poor nutrition, no exercise, sleep disruption. Step 5: Cross-reference with subjective_journal for emotional eating patterns. Produce: 1) Daily health summary — meals logged, macro breakdown, workout status, health_score, 2) Immediate alerts — missed meals, poor nutrition, inactivity flags, 3) Today''s health priorities — meal planning, workout scheduling, hydration targets, 4) Emotional eating correlation — any stress eating patterns detected. If all healthy: reply HEARTBEAT_OK. If concerns detected: produce brief with specific recommendations.","priority":"P2"}', 'active', 0, 0, 0, 0, (strftime('%s','now')*1000), 1),
('physician-weekly-review', 'physician-health', 'Weekly Health Review', 'Weekly nutritional and fitness analysis with adherence gap detection', 'cron', '0 15 * * 0', 'custom_prompt', '{"prompt":"Execute Weekly Health Review. Step 1: Query diet_log with period=past_week for comprehensive nutritional analysis. Step 2: Calculate weekly macro balance — protein, carbs, fats vs targets. Step 3: Analyze workout compliance — exercise frequency, intensity progression, recovery patterns. Step 4: Identify adherence gaps — where is user falling short of health targets? Step 5: Check meal timing patterns — eating window, meal consistency, hydration patterns. Step 6: Cross-reference with activity_types for target compliance. Produce: 1) Weekly nutrition report — macro balance, caloric alignment, micronutrient coverage, 2) Workout compliance summary — frequency, intensity, recovery, 3) Adherence gap analysis — targets met vs missed, patterns identified, 4) Meal pattern insights — timing consistency, eating windows, 5) Next week recommendations — specific adjustments needed. Save weekly health summary to reports DB via lifeos_create_entry(database=''reports''). SYSTEMIC FLAG CHECK: If adherence below 60% for the week or health_score declining 3+ consecutive days → send message.send to coo-productivity (who manages Physician) and ceo-strategic if systemic. Do NOT write to systemic_journal.","priority":"P1"}', 'active', 0, 0, 0, 0, (strftime('%s','now')*1000), 1),
('physician-monthly-synthesis', 'physician-health', 'Monthly Health Synthesis', 'Monthly comprehensive health assessment with deficiency detection and trajectory analysis', 'cron', '0 13 L * *', 'custom_prompt', '{"prompt":"Execute Monthly Health Synthesis. Step 1: Query diet_log with period=past_month for comprehensive nutritional data. Step 2: Analyze monthly nutritional adequacy — persistent macro imbalances, micronutrient deficiency patterns. Step 3: Review health trajectory — health_score trends, energy patterns, recovery quality over the month. Step 4: Detect nutritional deficiencies — patterns suggesting specific vitamin/mineral gaps. Step 5: Correlate health with other domains — productivity (COO), emotional (CPO), social (CRO). Step 6: Generate monthly health synthesis report. Produce: 1) Monthly health assessment — nutrition, activity, sleep, recovery overview, 2) Nutritional deficiency report — detected patterns, recommended interventions, 3) Health trajectory analysis — improving, stable, or declining trends, 4) Cross-domain correlation insights — how health affects other life domains, 5) Next month health priorities — specific targets, interventions, preventive actions. Save comprehensive monthly health report to reports DB. Update months DB with health summary if applicable. SYSTEMIC FLAG CHECK: If health_score declining month-over-month, or nutritional deficiencies persisting 2+ months, or cross-domain health impact detected → send message.send to ceo-strategic with systemic health pattern flag.","priority":"P1"}', 'active', 0, 0, 0, 0, (strftime('%s','now')*1000), 1),
('physician-quarterly-review', 'physician-health', 'Quarterly Health Review', 'Quarterly health OKR assessment with long-term trends and preventive health reminders', 'cron', '0 10 1 1,4,7,10 *', 'custom_prompt', '{"prompt":"Execute Quarterly Health Review. Step 1: Aggregate all health data from the past quarter — diet, activity, health_score, adherence. Step 2: Assess quarterly health OKR progress — are health targets being met? Step 3: Analyze long-term health trends — quarter-over-quarter comparison, trajectory direction. Step 4: Identify preventive health needs — upcoming checkups, screenings, vaccinations, dental visits. Step 5: Review health spending patterns from financial_log — supplement costs, medical expenses, gym memberships. Step 6: Generate strategic health posture assessment. Produce: 1) Quarterly health report — OKR achievement %, key metrics, trend direction, 2) Long-term health trajectory — quarter-over-quarter comparison, 3) Preventive health reminders — upcoming checkups, screenings, vaccinations, 4) Health spending analysis — budget vs actual, ROI on health investments, 5) Strategic health recommendations — lifestyle adjustments, intervention priorities, goal recalibration. Save comprehensive quarterly health report to reports DB. Create health-related tasks for preventive reminders via lifeos_create_entry(database=''tasks''). SYSTEMIC FLAG CHECK: If sustained health decline across quarter, or critical health risks identified, or health impacting strategic capacity → send message.send to ceo-strategic with critical health pattern flag.","priority":"P1"}', 'active', 0, 0, 0, 0, (strftime('%s','now')*1000), 1);
